"use client";

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type Transition,
} from "motion/react";
import {
  type ComponentPropsWithoutRef,
  type ReactElement,
  useEffect,
  useRef,
  useState,
} from "react";

import { cn } from "@/lib/utils";

const STATES = ["idle", "copied", "failed"] as const;
type CopyState = (typeof STATES)[number];

/** Props for a copy button. `value` is the text placed on the clipboard. */
export type CopyButtonProps = Omit<
  ComponentPropsWithoutRef<"button">,
  "children" | "value"
> & {
  value: string;
  /** The resting label, for example "Copy command". */
  label?: string;
  /** How long the confirmation stays before the button resets, in milliseconds. */
  resetAfter?: number;
  onCopied?: (value: string) => void;
};

const SWAP: Transition = { type: "spring", duration: 0.3, bounce: 0 };
// A fade is not motion, so reduced motion keeps it and drops the scale and blur.
const FADE: Transition = { duration: 0.15 };

function CopyGlyph() {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      aria-hidden="true"
      className="size-4"
    >
      <rect x="5.5" y="5.5" width="8" height="8" rx="2" />
      <path d="M10.5 3.5a2 2 0 0 0-2-2h-5a2 2 0 0 0-2 2v5a2 2 0 0 0 2 2" />
    </svg>
  );
}

function CheckGlyph() {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.75"
      aria-hidden="true"
      className="size-4"
    >
      <path
        d="m3 8.5 3.25 3.25L13 5"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function CrossGlyph() {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.75"
      aria-hidden="true"
      className="size-4"
    >
      <path d="m4 4 8 8M12 4l-8 8" strokeLinecap="round" />
    </svg>
  );
}

const GLYPHS = {
  idle: CopyGlyph,
  copied: CheckGlyph,
  failed: CrossGlyph,
} satisfies Record<CopyState, () => ReactElement>;

/**
 * Copies a value and confirms it in place: the icon and the label swap with
 * a short blur, then reset. The button keeps the width of its longest label,
 * so nothing beside it moves.
 */
export function CopyButton({
  value,
  label = "Copy",
  resetAfter = 1600,
  onCopied,
  className,
  onClick,
  ...buttonProps
}: CopyButtonProps) {
  const [state, setState] = useState<CopyState>("idle");
  const timer = useRef<number | null>(null);
  const reduceMotion = useReducedMotion();
  const labels = { idle: label, copied: "Copied", failed: "Copy failed" } satisfies Record<CopyState, string>;
  const Glyph = GLYPHS[state];
  const swap = reduceMotion ? FADE : SWAP;
  const hidden = reduceMotion
    ? { opacity: 0 }
    : { opacity: 0, scale: 0.8, filter: "blur(4px)" };

  useEffect(
    () => () => {
      if (timer.current !== null) window.clearTimeout(timer.current);
    },
    [],
  );

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(value);
      setState("copied");
      onCopied?.(value);
    } catch {
      setState("failed");
    }
    if (timer.current !== null) window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => setState("idle"), resetAfter);
  };

  return (
    <>
      <button
        {...buttonProps}
        type="button"
        onClick={(event) => {
          onClick?.(event);
          if (!event.defaultPrevented) void copy();
        }}
        className={cn(
          "inline-flex min-h-11 cursor-pointer touch-manipulation items-center gap-2 rounded-full border border-border bg-background px-4 text-sm font-medium text-foreground outline-none sm:min-h-9",
          "motion-safe:transition motion-safe:duration-150 hover:bg-muted active:scale-97",
          "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
          "disabled:cursor-not-allowed disabled:opacity-50",
          className,
        )}
      >
        <span className="grid size-4 place-items-center">
          <AnimatePresence mode="popLayout" initial={false}>
            <motion.span
              key={state}
              initial={hidden}
              animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }}
              exit={hidden}
              transition={swap}
              className="col-start-1 row-start-1 flex"
            >
              <Glyph />
            </motion.span>
          </AnimatePresence>
        </span>
        {/* Every label sits in one grid cell, so the cell is as wide as the longest and the button never resizes. */}
        <span className="grid">
          {STATES.map((key) => (
            <motion.span
              key={key}
              aria-hidden={key !== state}
              initial={false}
              animate={
                key === state
                  ? { opacity: 1, filter: "blur(0px)" }
                  : {
                      opacity: 0,
                      filter: reduceMotion ? "blur(0px)" : "blur(4px)",
                    }
              }
              transition={swap}
              className="col-start-1 row-start-1 whitespace-nowrap"
            >
              {labels[key]}
            </motion.span>
          ))}
        </span>
      </button>
      {/* Outside the button, so the announcement is not also read as part of its name. */}
      <span className="sr-only" role="status">
        {state === "idle" ? "" : labels[state]}
      </span>
    </>
  );
}
